"use client"

import { Thermometer, Flame, Wind, Activity } from "lucide-react"
import { motion } from "framer-motion"

const TabNavigation = ({ activeTab, onTabChange, estadisticas }) => {
  const tabs = [
    {
      id: "WRF",
      label: "WRF",
      icon: Thermometer,
      description: "Modelo meteorológico",
      count: estadisticas?.variables_wrf?.length || 0,
    },
    {
      id: "FWI",
      label: "FWI",
      icon: Flame,
      description: "Índice de peligro de incendio",
      count: 1,
    },
    {
      id: "Gases",
      label: "Gases",
      icon: Activity,
      description: "Medición de gases",
      count: 2,
    },
    {
      id: "Vientos",
      label: "Vientos",
      icon: Wind,
      description: "Ráfagas en rutas",
      count: 1,
    },
  ]

  return (
    <div className="bg-white rounded-xl shadow-md p-4 flex justify-center">
      <div className="flex flex-wrap gap-3 justify-center relative">
        {tabs.map((tab, idx) => {
          const Icon = tab.icon;
          const isActive = activeTab === tab.id;
          return (
            <button
              key={tab.id}
              onClick={() => onTabChange(tab.id)}
              className={`relative px-6 py-3 rounded-full font-semibold text-base md:text-lg flex items-center gap-2 transition-all duration-200
                ${isActive ? "bg-gradient-to-r from-blue-600 to-indigo-600 text-white shadow-lg" : "bg-gray-100 text-gray-700 hover:bg-blue-50"}
              `}
              style={{ minWidth: 140 }}
            >
              <Icon className={`h-5 w-5 ${isActive ? "text-white" : "text-blue-600"}`} />
              <span>{tab.label}</span>
              {isActive && (
                <motion.div
                  layoutId="tab-underline"
                  className="absolute left-4 right-4 -bottom-1 h-1 rounded-full bg-gradient-to-r from-blue-400 to-indigo-400"
                  transition={{ type: "spring", stiffness: 400, damping: 30 }}
                />
              )}
            </button>
          )
        })}
      </div>
    </div>
  )
}

export default TabNavigation
